      "efsm.infeasible": "\u4E0D\u53EF\u884C\u2014\u2014\u5B88\u885B\u4E92\u76F8\u77DB\u76FE\uFF0C\u6C92\u6709\u4EFB\u4F55\u8F38\u5165\u80FD\u540C\u6642\u6EFF\u8DB3",
      "efsm.solved": "\u6C42\u89E3\u5668\u9078\u5B9A amount = {val}",
      "efsm.compare.title": "\u7D14 FSM vs EFSM \u8DEF\u5F91\u6578",
